import React from 'react';
import { Html5Audio, Sequence, interpolate, staticFile } from 'remotion';

const FPS = 30;

// Narration lines (generated by scripts/narration.py). `at` = start in seconds,
// `dur` = clip length in seconds, used to duck the music under the voice.
export const VOICE_OVER = [
  { file: 'audio/vo1.wav', at: 0.4, dur: 1.96 }, // Snap your plate. Know your calories.
  { file: 'audio/vo2.wav', at: 3.1, dur: 4.76 }, // ...scans your meal...
  { file: 'audio/vo3.wav', at: 9.3, dur: 3.65 }, // Track every macro, every day...
  { file: 'audio/vo4.wav', at: 14.2, dur: 4.33 }, // Log by photo or text...
  { file: 'audio/vo5.wav', at: 19.0, dur: 2.54 }, // PlateSnap AI. Download free today.
];

const MUSIC_FULL = 0.55;
const MUSIC_DUCKED = 0.22;
const DUCK_FADE = 0.25; // seconds

/** Music volume at a given frame: ducked while the narrator speaks, faded out at the end. */
const musicVolume = (frame: number, totalFrames: number) => {
  const t = frame / FPS;
  let duck = 0;
  for (const v of VOICE_OVER) {
    const d = interpolate(t, [v.at - DUCK_FADE, v.at, v.at + v.dur, v.at + v.dur + DUCK_FADE], [0, 1, 1, 0], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
    duck = Math.max(duck, d);
  }
  const base = MUSIC_FULL - (MUSIC_FULL - MUSIC_DUCKED) * duck;
  const fadeOut = interpolate(frame, [totalFrames - 45, totalFrames], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  return base * fadeOut;
};

export const Soundtrack: React.FC<{ totalFrames: number }> = ({ totalFrames }) => (
  <>
    <Html5Audio src={staticFile('audio/music.wav')} volume={(f) => musicVolume(f, totalFrames)} />
    {VOICE_OVER.map((v) => (
      <Sequence key={v.file} from={Math.round(v.at * FPS)} name={v.file}>
        <Html5Audio src={staticFile(v.file)} volume={1} />
      </Sequence>
    ))}
  </>
);
